package org.dialoguecutter;
import android.app.*; import android.os.*; import android.content.*; import android.net.Uri; import android.widget.*; import android.provider.*; import android.media.MediaMetadataRetriever; import java.io.*; import java.util.*; import java.util.regex.*; import java.nio.charset.StandardCharsets;
import androidx.media3.common.*; import androidx.media3.effect.Presentation; import androidx.media3.transformer.*;
@androidx.media3.common.util.UnstableApi
public class MainActivity extends Activity {
 Uri movie,folder; ArrayList<Uri> subs=new ArrayList<>(); TextView status; EditText gap,pad,height; Button start; Transformer transformer; File temp; Handler handler=new Handler();
 static class Cue {long a,b; String text; Cue(long a,long b,String t){this.a=a;this.b=b;this.text=t;}}
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,32,32,32); ScrollView sc=new ScrollView(this);sc.addView(l);setContentView(sc); TextView title=new TextView(this);title.setText("Dialogue Cutter");title.setTextSize(28);l.addView(title);button(l,"Select movie",()->pick(1,"video/*",false));button(l,"Select subtitle tracks",()->pick(2,"*/*",true));button(l,"Select output folder",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),3));gap=field(l,"Minimum gap (seconds)","10");pad=field(l,"Padding each side (seconds)","2");height=field(l,"Output height (pixels)","720");start=button(l,"Cut and export",()->run());status=new TextView(this);l.addView(status);}
 Button button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);l.addView(b);b.setOnClickListener(v->r.run());return b;}
 EditText field(LinearLayout l,String s,String d){TextView t=new TextView(this);t.setText(s);l.addView(t);EditText e=new EditText(this);e.setInputType(2);e.setText(d);l.addView(e);return e;}
 void pick(int n,String type,boolean multi){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType(type);i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multi);startActivityForResult(i,n);}
 protected void onActivityResult(int n,int r,Intent i){super.onActivityResult(n,r,i);if(r!=RESULT_OK||i==null)return;if(n==1)movie=i.getData();if(n==2){subs.clear();if(i.getClipData()!=null)for(int j=0;j<i.getClipData().getItemCount();j++)subs.add(i.getClipData().getItemAt(j).getUri());else if(i.getData()!=null)subs.add(i.getData());}if(n==3)folder=i.getData();status.setText("Movie: "+(movie!=null)+" | Tracks: "+subs.size()+" | Folder: "+(folder!=null));}
 long ms(String s){String[] p=s.split("[:,.]");return Long.parseLong(p[0])*3600000+Long.parseLong(p[1])*60000+Long.parseLong(p[2])*1000+Long.parseLong(p[3]);}
 String stamp(long n){return String.format(Locale.US,"%02d:%02d:%02d,%03d",n/3600000,n/60000%60,n/1000%60,n%1000);}
 ArrayList<Cue> read(Uri u)throws Exception{String s;try(InputStream in=getContentResolver().openInputStream(u)){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)o.write(buf,0,n);s=new String(o.toByteArray(),StandardCharsets.UTF_8).replace("\r","").replace("\uFEFF","");}ArrayList<Cue> out=new ArrayList<>();Pattern p=Pattern.compile("(\\d+:\\d+:\\d+[,\\.]\\d{3})\\s*-->\\s*(\\d+:\\d+:\\d+[,\\.]\\d{3})[^\\n]*\\n(.*)",Pattern.DOTALL);for(String block:s.trim().split("\\n[ \\t]*\\n")){Matcher m=p.matcher(block);if(m.find())out.add(new Cue(ms(m.group(1)),ms(m.group(2)),m.group(3)));}if(out.isEmpty())throw new IOException("No subtitle cues found");return out;}
 void run(){try{if(movie==null||folder==null||subs.isEmpty())throw new IOException("Select movie, subtitles and output folder");long g=1000L*Integer.parseInt(gap.getText().toString()),p=1000L*Integer.parseInt(pad.getText().toString());int h=Integer.parseInt(height.getText().toString());if(g<=2*p||h<144)throw new IOException("Gap must exceed twice padding; height must be at least 144");MediaMetadataRetriever mm=new MediaMetadataRetriever();mm.setDataSource(this,movie);long duration=Long.parseLong(mm.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));mm.release();ArrayList<ArrayList<Cue>> tracks=new ArrayList<>();ArrayList<Cue> all=new ArrayList<>();for(Uri u:subs){ArrayList<Cue> t=read(u);tracks.add(t);all.addAll(t);}all.sort(Comparator.comparingLong(c->c.a));ArrayList<long[]> spans=new ArrayList<>();for(Cue c:all){if(c.b>duration||c.a<0||c.b<=c.a)throw new IOException("Invalid cue or subtitle exceeds movie duration");if(spans.isEmpty()||c.a-spans.get(spans.size()-1)[1]>=g)spans.add(new long[]{c.a,c.b});else {long[] last=spans.get(spans.size()-1);last[1]=Math.max(last[1],c.b);}}for(int j=0;j<spans.size();j++){long[] s=spans.get(j);s[0]=j==0&&s[0]<g?0:Math.max(0,s[0]-p);s[1]=j==spans.size()-1&&duration-s[1]<g?duration:Math.min(duration,s[1]+p);}
 // Only the first span may preserve the opening gap.
 for(int j=1;j<spans.size();j++){long[] s=spans.get(j);if(s[0]==0)throw new IOException("Overlapping cuts");}
 ArrayList<EditedMediaItem> items=new ArrayList<>();long total=0;for(long[] s:spans){total+=s[1]-s[0];MediaItem m=new MediaItem.Builder().setUri(movie).setClippingConfiguration(new MediaItem.ClippingConfiguration.Builder().setStartPositionMs(s[0]).setEndPositionMs(s[1]).build()).build();items.add(new EditedMediaItem.Builder(m).setEffects(new Effects(Collections.emptyList(),Collections.singletonList(Presentation.createForHeight(h)))).build());}Composition composition=new Composition.Builder(new EditedMediaItemSequence(items)).build();temp=new File(getCacheDir(),"cut.mp4");temp.delete();start.setEnabled(false);status.setText("Exporting "+spans.size()+" segments; planned duration "+total/1000+" seconds");transformer=new Transformer.Builder(this).setVideoMimeType(MimeTypes.VIDEO_H264).setAudioMimeType(MimeTypes.AUDIO_AAC).addListener(new Transformer.Listener(){public void onCompleted(Composition c,ExportResult result){new Thread(()->{try{save(tracks,spans);runOnUiThread(()->{status.setText("Export complete");start.setEnabled(true);});}catch(Exception e){runOnUiThread(()->fail(e));}}).start();}public void onError(Composition c,ExportResult r,ExportException e){fail(e);}}).build();transformer.start(composition,temp.getAbsolutePath());handler.postDelayed(new Runnable(){public void run(){if(start.isEnabled())return;ProgressHolder ph=new ProgressHolder();if(transformer.getProgress(ph)==Transformer.PROGRESS_STATE_AVAILABLE)status.setText("Exporting: "+ph.progress+"%");handler.postDelayed(this,1000);}},1000);
 }catch(Exception e){fail(e);}}
 void fail(Exception e){status.setText(e.toString());start.setEnabled(true);}
 Uri output(String name,String mime)throws Exception{return DocumentsContract.createDocument(getContentResolver(),DocumentsContract.buildDocumentUriUsingTree(folder,DocumentsContract.getTreeDocumentId(folder)),mime,name);}
 void save(ArrayList<ArrayList<Cue>> tracks,ArrayList<long[]> spans)throws Exception{try(InputStream in=new FileInputStream(temp);OutputStream out=getContentResolver().openOutputStream(output("Dialogue-cut.mp4","video/mp4"))){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}for(int j=0;j<tracks.size();j++){StringBuilder b=new StringBuilder();int k=1;for(Cue c:tracks.get(j)){long offset=0;for(long[] s:spans){if(c.a>=s[0]&&c.b<=s[1]){b.append(k++).append('\n').append(stamp(offset+c.a-s[0])).append(" --> ").append(stamp(offset+c.b-s[0])).append('\n').append(c.text).append("\n\n");break;}offset+=s[1]-s[0];}}try(OutputStream out=getContentResolver().openOutputStream(output("Dialogue-track-"+(j+1)+".srt","application/x-subrip"))){out.write(b.toString().getBytes(StandardCharsets.UTF_8));}}temp.delete();}
}
